{#- Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/topic-chips.json
    A centered row of topic pills: links where a topic has an address, else buttons. tone inverse: on a dark band with an icon per topic; default: outlined.
    Props (p): topics, tone. -#}
{%- set v_topics = (p.topics ?? null) -%}
{%- set v_tone = (p.tone ?? 'default') -%}
{%- set c_3 -%}
  {%- for v_topic in og_l(v_topics) %}
    {%- if og_t(og_eq(v_tone, 'inverse')) %}
      {%- set c_1 -%}
        {%- if og_t(og_get(v_topic, ['icon'])) %}
          {{ include('icons/LucideIcon.html.twig', {'name': og_s(og_get(v_topic, ['icon'])), 'size': 16}, with_context = false) }}
        {%- endif %}
        {{ og_text(og_get(v_topic, ['name'])) }}
      {%- endset -%}
      {{ include('compose/Button.html.twig', {'href': og_url(og_s(og_get(v_topic, ['href']))), 'variant': 'ghost', 'size': 'sm', 'class': 'gap-2 text-background inset-ring-background/30 hover:bg-background/10', 'attrs': og_attrs(['data-testid', 'hero-topic']), 'children': c_1}, with_context = false) }}
    {%- else %}
      {%- set c_2 -%}
        {{ og_text(og_get(v_topic, ['name'])) }}
      {%- endset -%}
      {{ include('compose/Button.html.twig', {'href': og_url(og_s(og_get(v_topic, ['href']))), 'variant': 'outline', 'size': 'sm', 'attrs': og_attrs(['data-testid', 'hero-topic']), 'children': c_2}, with_context = false) }}
    {%- endif %}
  {%- endfor %}
{%- endset -%}
{{ include('compose/Group.html.twig', {'gap': '2', 'align': 'center', 'justify': 'center', 'class': 'flex-wrap', 'attrs': og_attrs(['data-testid', 'hero-topics']), 'children': c_3}, with_context = false) }}
